CREATE OR REPLACE FUNCTION public.compute_staff_payroll(p_staff_id uuid, p_period_start date, p_period_end date)
 RETURNS TABLE(total_hours numeric, regular_pay numeric, net_tips numeric)
 LANGUAGE sql
 STABLE
AS $function$
  select
    coalesce(sum(hours_worked), 0)                          as total_hours,
    coalesce(sum(hours_worked * hourly_rate), 0)            as regular_pay,
    coalesce(sum(cash_tips + card_tips - tip_out), 0)       as net_tips
  from shifts
  where staff_id = p_staff_id
    and shift_date between p_period_start and p_period_end
    and end_time is not null;           -- only completed shifts
$function$;

CREATE OR REPLACE FUNCTION public.create_organization(org_name text, org_slug text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  new_org_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  insert into organizations (name, slug, created_by)
  values (org_name, org_slug, auth.uid())
  returning id into new_org_id;

  insert into memberships (user_id, organization_id, role)
  values (auth.uid(), new_org_id, 'owner');

  return new_org_id;
end; $function$;

CREATE OR REPLACE FUNCTION public.dd_delete_account(p_org_id uuid, p_verification_id uuid, p_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_code_org    UUID;
  v_employee_id UUID;
  v_before      JSONB;
BEGIN
  SELECT organization_id INTO v_code_org
  FROM dd_verification_codes
  WHERE id = p_verification_id
  FOR UPDATE;

  IF v_code_org IS NULL OR v_code_org <> p_org_id THEN
    RAISE EXCEPTION 'Verification session not found.';
  END IF;

  -- Capture the prior state before mutating, so the audit row is accurate even
  -- though it is written after the update.
  SELECT employee_id,
         jsonb_build_object('account_last4', account_last4, 'bank_name', bank_name)
    INTO v_employee_id, v_before
  FROM direct_deposit_accounts
  WHERE id = p_account_id
    AND organization_id = p_org_id
  FOR UPDATE;

  IF v_employee_id IS NULL THEN
    RAISE EXCEPTION 'Account not found.';
  END IF;

  UPDATE dd_verification_codes
  SET is_used = true, verified_at = NOW()
  WHERE id = p_verification_id;

  UPDATE direct_deposit_accounts
  SET is_active = false, updated_at = NOW()
  WHERE id = p_account_id
    AND organization_id = p_org_id;

  -- Matches the value the app has always written, so existing audit history
  -- stays queryable with one action name.
  INSERT INTO dd_audit_log (organization_id, employee_id, action, before_state, code_id)
  VALUES (p_org_id, v_employee_id, 'ACCOUNT_DELETED', v_before, p_verification_id);

  RETURN v_before;
END;
$function$;

