CREATE OR REPLACE FUNCTION public.pos_apply_item_sales(p_org uuid, p_sale_date date, p_components jsonb)
 RETURNS TABLE(moved_item_id uuid, moved_delta numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  rec        RECORD;
  v_applied  NUMERIC;
  v_delta    NUMERIC;
BEGIN
  FOR rec IN
    SELECT (e->>'item_id')::UUID  AS item_id,
           (e->>'qty')::NUMERIC   AS qty
    FROM jsonb_array_elements(COALESCE(p_components, '[]'::JSONB)) e
  LOOP
    -- FOR UPDATE so two overlapping syncs cannot both read the same prior
    -- applied figure and each subtract the full amount.
    SELECT a.applied_qty INTO v_applied
    FROM pos_stock_applications a
    WHERE a.organization_id   = p_org
      AND a.sale_date         = p_sale_date
      AND a.inventory_item_id = rec.item_id
    FOR UPDATE;

    v_delta := rec.qty - COALESCE(v_applied, 0);
    CONTINUE WHEN v_delta = 0;

    -- Clamped at zero: negative stock is rejected everywhere else in the app,
    -- and a bar whose opening count was never entered would otherwise drift
    -- deeply negative on its first sync. The usage log below still records the
    -- true delta, so consumption analytics stays accurate even when the clamp
    -- bites — the two can legitimately disagree until the next recount.
    UPDATE inventory_items
    SET current_stock = GREATEST(0, COALESCE(current_stock, 0) - v_delta)
    WHERE id = rec.item_id
      AND organization_id = p_org;

    -- Item belongs to another org, or no longer exists. Skip it rather than
    -- recording an application we did not make.
    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    -- The cast is required, not decorative. `reason` is the enum usage_reason,
    -- and a CASE whose branches are both unknown literals resolves to TEXT —
    -- which Postgres will not implicitly coerce to an enum. Without ::usage_reason
    -- every depletion fails at runtime with "column reason is of type
    -- usage_reason but expression is of type text".
    INSERT INTO usage_logs (organization_id, item_id, quantity, reason, note)
    VALUES (
      p_org,
      rec.item_id,
      ABS(v_delta),
      (CASE WHEN v_delta > 0 THEN 'pos_sale' ELSE 'pos_reversal' END)::usage_reason,
      'POS sales for ' || TO_CHAR(p_sale_date, 'YYYY-MM-DD')
    );

    INSERT INTO pos_stock_applications
      (organization_id, sale_date, inventory_item_id, applied_qty)
    VALUES
      (p_org, p_sale_date, rec.item_id, rec.qty)
    ON CONFLICT (organization_id, sale_date, inventory_item_id)
    DO UPDATE SET applied_qty = EXCLUDED.applied_qty, updated_at = NOW();

    moved_item_id := rec.item_id;
    moved_delta   := v_delta;
    RETURN NEXT;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.pos_item_match_key(p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- Collapse runs of whitespace, trim, lowercase.
  SELECT lower(btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g')));
$function$;

CREATE OR REPLACE FUNCTION public.prune_jsonb_payloads(p_audit_retain_days integer DEFAULT 2555, p_ai_retain_days integer DEFAULT 400)
 RETURNS TABLE(audit_rows_stripped integer, ai_rows_stripped integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_audit INTEGER := 0;
  v_ai    INTEGER := 0;
BEGIN
  UPDATE dd_audit_log
  SET before_state = NULL, after_state = NULL
  WHERE created_at < NOW() - make_interval(days => p_audit_retain_days)
    AND (before_state IS NOT NULL OR after_state IS NOT NULL);
  GET DIAGNOSTICS v_audit = ROW_COUNT;

  -- Guarded: bar_messages.ai_breakdown is added by a later migration in some
  -- environments, and this function must not fail where it does not exist yet.
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name   = 'bar_messages'
      AND column_name  = 'ai_breakdown'
  ) THEN
    EXECUTE format(
      'UPDATE bar_messages SET ai_breakdown = NULL
         WHERE created_at < NOW() - make_interval(days => %L::INTEGER)
           AND ai_breakdown IS NOT NULL',
      p_ai_retain_days
    );
    GET DIAGNOSTICS v_ai = ROW_COUNT;
  END IF;

  RETURN QUERY SELECT v_audit, v_ai;
END;
$function$;

CREATE OR REPLACE FUNCTION public.rate_limit_hit(p_bucket text, p_limit integer, p_window_seconds integer)
 RETURNS TABLE(allowed boolean, remaining integer, retry_after_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_window_start TIMESTAMPTZ;
  v_hits         INTEGER;
BEGIN
  IF p_window_seconds <= 0 OR p_limit < 0 THEN
    RAISE EXCEPTION 'rate_limit_hit: limit must be >= 0 and window must be > 0';
  END IF;

  -- Floor now() to the window boundary so every instance agrees on which
  -- window a request falls in without coordinating.
  --
  -- extract(epoch ...) returns numeric on PG14+, and there is no
  -- to_timestamp(numeric) — it resolves only via an implicit cast. Made
  -- explicit so the overload can never be ambiguous.
  v_window_start := to_timestamp(
    (floor(extract(EPOCH FROM now()) / p_window_seconds) * p_window_seconds)::DOUBLE PRECISION
  );

  INSERT INTO rate_limits AS rl (bucket, window_start, hits)
  VALUES (p_bucket, v_window_start, 1)
  ON CONFLICT (bucket, window_start)
  DO UPDATE SET hits = rl.hits + 1
  RETURNING rl.hits INTO v_hits;

  RETURN QUERY SELECT
    v_hits <= p_limit,
    GREATEST(p_limit - v_hits, 0),
    CEIL(EXTRACT(EPOCH FROM
      (v_window_start + make_interval(secs => p_window_seconds)) - now()
    ))::INTEGER;
END;
$function$;

CREATE OR REPLACE FUNCTION public.rate_limit_sweep(p_older_than_hours integer DEFAULT 24)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_deleted INTEGER;
BEGIN
  DELETE FROM rate_limits
  WHERE window_start < now() - make_interval(hours => p_older_than_hours);
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_updated_at()
